// Monta o payload final pro endpoint /integrations/whatsapp/send.
// Aceita campos diretos no body do webhook OU dentro de $json.body (n8n
// embrulha em body quando responseMode='lastNode').
const raw = $input.item.json.body ?? $input.item.json;

function pick(obj, keys) {
  const out = {};
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && v !== '') out[k] = v;
  }
  return out;
}

const allowed = [
  'conversationId',
  'phone',
  'inboxId',
  'contactName',
  'type',
  'content',
  'mediaUrl',
  'mediaBase64',
  'mimeType',
  'filename',
  'sender_type',
  'metadata',
];

const payload = pick(raw, allowed);

if (!payload.type) {
  throw new Error("Campo 'type' obrigatório (text|image|audio|document)");
}
if (!payload.conversationId && !payload.phone) {
  throw new Error("Informe 'conversationId' OU 'phone'");
}

return [{ json: { payload } }];

// Repassa a resposta do GLEPS para quem chamou o webhook.
// Se o HTTP node falhou (4xx/5xx ou network), $json.error existe; senão
// vem $json.statusCode + $json.body com o payload de sucesso.
const item = $input.item.json;

if (item.error) {
  return [{
    json: {
      ok: false,
      status: item.error.httpCode ?? 500,
      error: item.error.message ?? 'Falha desconhecida',
      details: item.error,
    },
  }];
}

const status = item.statusCode ?? 200;
const body = item.body ?? item;
return [{
  json: {
    ok: status >= 200 && status < 300,
    status,
    ...body,
  },
}];
